function kthInDictionaryOrder(n: number, k: number): number {
  let cur = 1;
  for (let i = 1; i < k; i++) {
    if (cur * 10 <= n) cur *= 10;
    else {
      while (cur % 10 === 9 || cur + 1 > n) cur = Math.floor(cur / 10);
      cur++;
    }
  }
  return cur;
}

