function kthInDictionaryOrder(n: number, k: number): number {
  const subtree = (p: number): number => {
    let count = 0, first = p, last = p;
    while (first <= n) {
      count += Math.min(n, last) - first + 1;
      first *= 10;
      last = last * 10 + 9;
    }
    return count;
  };
  let cur = 1, left = k - 1;
  while (left > 0) {
    const size = subtree(cur);
    if (size <= left) { left -= size; cur++; }
    else { left--; cur *= 10; }
  }
  return cur;
}

